A = dir(110);
B = dir(290);
C = intersectionpoint(arc(O,1,0,180),A--B);

draw(Circle(O,1));
draw(A--B);
draw(A--O--B);

label("$A$", A, N);
label("$B$", B, S);
label("$O$", O, SE);
label("$6$", (A + B)/2, S);
[/asy]

